# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAMİYET\'İN DOĞUŞU: VAHİY SÜRECİ VE MEKKE DÖNEMİ (610-622)</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Tevhid Halkasının Sonuncusu</text>\n  <text x="50" y="105" font-size="11.5" fill="#334155">• Hz. Âdem\'den başlayan tevhid dininin</text>\n  <text x="62" y="123" font-size="11" fill="#475569">kemâle erdirilmiş son halkasıdır (Mâide, 3).</text>\n  <text x="50" y="150" font-size="11.5" fill="#334155">• 610 yılı Ramazan ayında Hira Mağarası\'nda</text>\n  <text x="62" y="168" font-size="11" fill="#475569">Alak Suresi 1-5. ayetlerle vahiy başladı.</text>\n  <text x="50" y="195" font-size="11.5" fill="#334155">• İlk Müslümanlar: Hz. Hatice, Hz. Ali,</text>\n  <text x="62" y="213" font-size="11" fill="#475569">Hz. Zeyd bin Harise ve Hz. Ebû Bekir.</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Mekke Döneminin Temel Aşamaları</text>\n  <text x="380" y="105" font-size="11.5" fill="#334155">• 3 yıl gizli davet (Dârü\'l-Erkam merkezi),</text>\n  <text x="392" y="123" font-size="11" fill="#475569">ardından açıktan tebliğ ve şirkle mücadele.</text>\n  <text x="380" y="150" font-size="11.5" fill="#334155">• Habeşistan Hicreti (615-616), 3 yıllık</text>\n  <text x="392" y="168" font-size="11" fill="#475569">boykot, Hüzün Yılı, Taif Yolculuğu, İsra-Miraç.</text>\n  <text x="380" y="195" font-size="11.5" fill="#334155">• I. ve II. Akabe Biatları (621-622) ile</text>\n  <text x="392" y="213" font-size="11" fill="#475569">Medine\'ye Hicret zemininin hazırlanması.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MEDİNE DÖNEMİ (622-632): KURUMSALLAŞMA VE FETİH</text>\n  <rect x="30" y="50" width="200" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="130" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Toplumsal İnşa</text>\n  <text x="45" y="105" font-size="11" fill="#334155">• Mescid-i Nebevî ve Suffe</text>\n  <text x="45" y="130" font-size="11" fill="#334155">• Muâhât (Ensar-Muhacir</text>\n  <text x="55" y="148" font-size="11" fill="#475569">kardeşleştirilmesi)</text>\n  <text x="45" y="173" font-size="11" fill="#334155">• Medine Vesikası (Çok</text>\n  <text x="55" y="191" font-size="11" fill="#475569">kültürlü vatandaşlık sözl.)</text>\n  <rect x="250" y="50" width="200" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Savunma ve Antlaşmalar</text>\n  <text x="265" y="105" font-size="11" fill="#334155">• Bedir (624), Uhud (625)</text>\n  <text x="275" y="123" font-size="11" fill="#475569">ve Hendek (627) Savaşları</text>\n  <text x="265" y="148" font-size="11" fill="#334155">• Hudeybiye Barışı (628):</text>\n  <text x="275" y="166" font-size="11" fill="#475569">İslam devletinin resmen</text>\n  <text x="275" y="184" font-size="11" fill="#475569">tanınması ve İslam\'a davet</text>\n  <text x="275" y="202" font-size="11" fill="#475569">mektupları gönderilmesi</text>\n  <rect x="470" y="50" width="200" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="570" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Fetih ve Veda (630-632)</text>\n  <text x="485" y="105" font-size="11" fill="#334155">• Mekke\'nin Fethi (630) ve</text>\n  <text x="495" y="123" font-size="11" fill="#475569">Kâbe\'nin putlardan arınması</text>\n  <text x="485" y="148" font-size="11" fill="#334155">• Veda Haccı ve Veda Hutbesi</text>\n  <text x="495" y="166" font-size="11" fill="#475569">(Evrensel insan hakları)</text>\n  <text x="485" y="191" font-size="11" fill="#334155">• 8 Haziran 632: Hz.</text>\n  <text x="495" y="209" font-size="11" fill="#475569">Peygamber\'in vefatı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HULEFÂ-Yİ RÂŞİDÎN DÖNEMİ (632-661) VE İSLAM\'IN YAYILIŞI</text>\n  <rect x="35" y="55" width="300" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Dört Halife Dönemi Hizmetleri</text>\n  <text x="50" y="108" font-size="11" fill="#334155">• Hz. Ebû Bekir: İç birliğin korunması ve</text>\n  <text x="62" y="125" font-size="11" font-weight="bold" fill="#1e40af">Kur\'an-ı Kerim\'in Mushaf haline getirilmesi.</text>\n  <text x="50" y="147" font-size="11" fill="#334155">• Hz. Ömer: Kudüs, Suriye, Irak, İran ve Mısır\'ın</text>\n  <text x="62" y="164" font-size="11" fill="#475569">fethi; Hicri takvim ve devlet teşkilatlanması.</text>\n  <text x="50" y="186" font-size="11" fill="#334155">• Hz. Osman: Mushafın çoğaltılması, ilk donanma.</text>\n  <text x="50" y="208" font-size="11" fill="#334155">• Hz. Ali: İlmî derinlik ve iç istikrar mücadelesi.</text>\n  <rect x="365" y="55" width="300" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="515" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kıtalara Yayılış ve Medeniyet Havzaları</text>\n  <text x="380" y="108" font-size="11" fill="#334155">• Emeviler ve Abbasiler döneminde Kuzey</text>\n  <text x="392" y="126" font-size="11" fill="#475569">Afrika, Endülüs (İspanya) ve Mâverâünnehir.</text>\n  <text x="380" y="150" font-size="11" fill="#334155">• 751 Talas Savaşı sonrası Türklerin kitleler</text>\n  <text x="392" y="168" font-size="11" fill="#475569">halinde İslam\'ı kabulü (Karahanlı, Selçuklu,</text>\n  <text x="392" y="186" font-size="11" fill="#475569">Osmanlı ile Anadolu ve Balkanlara yayılış).</text>\n  <text x="380" y="210" font-size="11" fill="#334155">• Tüccar ve sûfîlerle Güneydoğu Asya\'ya ulaşım.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
